let GOD=false;   // god mode (console: god): no damage, no knockouts, water never runs out -- for testing and recording
const P={x:0,z:39,y:0,vy:0,kx:0,kz:0,fa:Math.PI,yaw:0,pitch:0.32,digT:0,digPh:0,anim:0,grounded:true,moving:false};
P.y=groundAt(P.x,P.z);
let me=null,meL=null;
const KEYS={};let digHeld=false;

/* first / third person (V) and the first-person shovel */
let FP=true;   // JT 2026-10-01: first person is the game now (V still switches, for the time being)
const pc=v=>clamp(v,FP?-1.35:-0.15,FP?1.35:1.25);
function toggleView(){FP=!FP;if(me&&!me.model)me.g.visible=!FP;P.pitch=FP?0.05:0.32;toast(FP?'First person. Press V to switch back.':'Third person','',1500)}
const vm=new T.Group();
{const hd=new T.Mesh(new T.CylinderGeometry(0.02,0.02,0.9,5),M(0x8a6440));hd.rotation.x=Math.PI/2;hd.position.z=-0.25;const bl=new T.Mesh(new T.BoxGeometry(0.22,0.02,0.26),M(0x7d8288));bl.position.z=-0.78;const sh=new T.Group();sh.rotation.x=-0.35;sh.add(hd,bl);vm.add(sh)}
vm.position.set(0.34,-0.4,-0.55);vm.visible=false;camera.add(vm);
/* Once the camper model loads, swap the box shovel above for the Blender one the camper carries (camper.glb's
   *_R_Shovel* meshes, rigid children of forearm.R). Laid along -Z like the box one: blade out front, scoop up. */
let vmBlender=false;const VM_SHOVEL=[];   // the first-person shovel's meshes (25-people.js spadeLook darkens a sharpened one)
function vmUseModelShovel(){
  vmBlender=true;
  const parts=[];MODEL.scene.traverse(n=>{if(n.isMesh&&/^CGLCamper_R_Shovel/.test(n.name))parts.push(n)});
  const shaft=parts.find(n=>/Shaft$/.test(n.name));if(!shaft)return;
  const inv=new T.Matrix4().copy(shaft.matrix).invert(),g=new T.Group();   // shovel space: the shaft's own frame, +Y = handle end
  const mk=n=>{const m=new T.Mesh(n.geometry,n.material);m.matrixAutoUpdate=false;m.matrix.multiplyMatrices(inv,n.matrix);shovelPart(m);m.userData.longPart=/Long$/.test(n.name);m.userData.campPart=/_R_Shovel(Shaft|Cap)$/.test(n.name);VM_SHOVEL.push(m);return m};
  for(const n of parts)if(!/Long$/.test(n.name))g.add(mk(n));
  const bb=new T.Box3().setFromObject(g),len=bb.max.y-bb.min.y;   // sized by the camp shovel; the long handle (when you've got it) just runs on past your hand
  for(const n of parts)if(/Long$/.test(n.name))g.add(mk(n));
  const s=1.1/len,holder=new T.Group();g.scale.setScalar(s);g.position.y=-bb.max.y*s;   // handle end at the holder's origin
  g.rotation.set(0,Math.PI/2,0);holder.add(g);   // roll: scoop side up
  holder.rotation.set(Math.PI/2+0.3,0.18,0);   // shovel runs down -Y from the handle: lay it out in front (-Z), blade lifted into view and angled in a touch
  holder.position.set(0,-0.02,0.3);
  const sh=vm.children[0];sh.clear();sh.add(holder);
}
function updateViewmodel(){if(!vmBlender&&MODEL.ready)vmUseModelShovel();if(me){spadeLook(me,S.up.spade);me.longShovel=!!S.up.long;me.noShovel=!S.up.shovel;for(const m of VM_SHOVEL)m.visible=shovelShows(me,m);if(me.shovel)me.shovel.visible=!me.noShovel}vm.visible=FP&&S.started&&!S.ko&&!twSt&&!tbSt&&!(me&&me.model);   // only for the box camper: with the model you see your own arms (fpBody, 70-player.js)
  if(!vm.visible)return;const d=P.anim===2?Math.sin(P.digPh*Math.PI):0,b=P.moving?Math.sin(performance.now()/110)*0.012:0;vm.rotation.x=-d*0.9;vm.position.set(0.34+b,-0.4-d*0.05+Math.abs(b),-0.55-d*0.2)}

function waterMax(){return (S.up.canteen3?230:S.up.canteen?160:100)+(myLevel()>=4?20:0)}
/* the gold rush (sim.js GOLD): your bucket holds this many holes' worth of sand (5, 10 or 15) */
/* starting with nothing (JT 2026-10-01): your sand goes in your bucket if you've bought one (to the sifter), else your
   gold pan (washed at the water drums), else on the pile. bucketMax is what it holds, in holes of sand. */
function bucketMax(){if(S.up.bucket&&backsackOn())return BACKSACK_HOLES[myBackTier()-1];   /* a backsack that holds at least as much as the bucket (86-backsack.js) */
  return S.up.bucket3?SIM.GOLD.buckets[2]:S.up.bucket2?SIM.GOLD.buckets[1]:S.up.bucket?SIM.GOLD.buckets[0]:S.up.pan?SIM.PAN:0}
const carrier=()=>S.up.bucket||S.up.bucket2||S.up.bucket3?'bucket':S.up.pan?'pan':null;
let noCarrierT=0;
let bucketWarnT=0;
function fillBucket(dd){   // dd: metres you just dug; a 5 ft hole is one hole of sand
  if(!(dd>0))return;const was=S.bucket,max=bucketMax(),c=carrier();
  if(!c){const now=performance.now();if(now-noCarrierT>25000){noCarrierT=now;toast('That sand\'s just going on the pile. A gold pan from the Supply Depot (10 gold) lets you take it to the water drums and wash it for gold.','',5500)}return}
  S.bucket=Math.min(max,S.bucket+dd/FIVE_FT);
  if(S.bucket>=max-1e-6&&was<max-1e-6){sfx.coin();toast(c==='pan'?'Your pan\'s full. Wash it at the water drums (F).':`Your bucket's full (${max} holes of sand). Take it back to the sifter in camp.`,'gold',5000)}
  else if(S.bucket>=max-1e-6){const now=performance.now();if(now-bucketWarnT>9000){bucketWarnT=now;toast(c==='pan'?'Your pan\'s full. Wash it at the water drums.':'Your bucket\'s full. The sand\'s just going on the pile. Sift it at camp.','',3000)}}
}
function digDepthMax(){return !S.up.shovel?SIM.HANDS.depth:S.up.long?EIGHT_FT:FIVE_FT}
/* toast variants (docs/ui-redesign-spec.md section 4): existing call sites keep passing the old
   class names ('good'/'gold'/'bad'/'') -- toast() maps them to the spec's success/reward/warning/
   neutral vocabulary (and picks an icon) so nothing elsewhere needs to change. An identical
   message+variant within 2s refreshes the existing toast's timer instead of stacking a duplicate. */
const TOAST_VARIANT={good:'success',gold:'reward',bad:'warning','':'neutral'};
const TOAST_ICON={success:'check',reward:'seed',warning:'lizard',neutral:'ping'};
const recentToasts=new Map();
function toast(msg,cls,ms){
  const variant=TOAST_VARIANT[cls||'']||'neutral',key=variant+'|'+msg,now=performance.now();
  const dup=recentToasts.get(key);
  if(dup&&now-dup.t<2000){
    dup.t=now;clearTimeout(dup.timer);dup.timer=setTimeout(()=>{dup.el.remove();recentToasts.delete(key)},ms||3600);
    dup.el.classList.remove('toast--refresh');void dup.el.offsetWidth;dup.el.classList.add('toast--refresh');
    return;
  }
  const el=document.createElement('div');el.className=`toast toast--${variant}`;el.setAttribute('role','status');
  const icon=document.createElement('span');icon.className='toast__icon';icon.setAttribute('aria-hidden','true');
  icon.innerHTML=`<svg class="ui-icon"><use href="#icon-${TOAST_ICON[variant]}"></use></svg>`;
  const txt=document.createElement('span');txt.className='toast__text';txt.textContent=msg;
  el.append(icon,txt);
  const box=$('#toasts');box.appendChild(el);while(box.children.length>4){const old=box.firstChild;for(const[k,v]of recentToasts)if(v.el===old){clearTimeout(v.timer);recentToasts.delete(k);break}old.remove()}
  const timer=setTimeout(()=>{el.remove();recentToasts.delete(key)},ms||3600);
  recentToasts.set(key,{el,t:now,timer});
}

/* ---------- digging ---------- */
let lastWarn=0;
function scoop(){
  if(S.inTown)return;
  if(hoverOn()){const n=performance.now();if(n-(scoop.hoverT||0)>2500){scoop.hoverT=n;toast('Step off your hoverboard to dig (Z).','',1800)}return}
  shoesDig();   /* hover shoes switch off quietly so you can dig in (88-hover.js) */   // no digging down in the buried town
  if(!inSinkhole()&&remoteNear(R=>R.f&32,SINK_RESCUE_R))return;   // E at a trapped friend's rim links hands (87-sinkhole.js), it doesn't dig
  if(vShoo())return;   // a well-timed swing while a vulture is diving close in front of you chases it off (83-vultures.js)
  if(rosterSwing())return;   // a hatchling, rattlesnake or scorpion in front of you: squash it (83-roster.js)
  if(javSwing())return;   // a live javelina in shovel reach gets whacked instead of the ground getting dug
  if(lionSwing())return;   // the mountain lion is in melee range: this shovel swing hits it instead of digging (see 85-lion.js)
  if(bonkSwing())return;   // a friend (or crew member) right in front of you: the swing bonks them instead (71-bonk.js)
  if(inSinkhole()){const now=performance.now();if(now-lastWarn>3000){lastWarn=now;toast('The walls are too steep and loose to dig footholds. Only a friend can pull you out.','bad')}return}
  const fx=Math.sin(P.fa),fz=Math.cos(P.fa);
  const tx=P.x+fx*1.1,tz=P.z+fz*1.1;
  let h=holeNear(P.x,P.z,HOLE_R*0.8)||holeNear(tx,tz,1.4);
  const now=performance.now();
  const cx=h?h.x:tx,cz=h?h.z:tz;
  if(inCamp(cx,cz)){if(now-lastWarn>2500){toast('No digging inside camp. Head out onto the lake bed.','bad');lastWarn=now}return}
  if(nearCampNoDig(cx,cz)){if(now-lastWarn>2500){toast('Too close to the camp fence. Dig past the white line.','bad');lastWarn=now}return}
  if(Math.max(Math.abs(cx),Math.abs(cz))>EDGE-2){if(now-lastWarn>2500){toast('That\'s the edge of the lake. Dig closer in.','bad');lastWarn=now}return}
  const maxD=digDepthMax();
  if(!h){h=addHole({x:r1(tx),z:r1(tz),d:0,mine:true,own:true})}
  if(h.d>=maxD-0.001){
    if(now-lastWarn>3000){lastWarn=now;if(!S.up.shovel)toast('That\'s as deep as you can dig with your hands. A camp shovel from the Supply Depot (25 gold) goes to 5 feet.');else if(maxD<EIGHT_FT)toast('That\'s 5 feet, as deep as your shovel reaches. A long-handled shovel from the Supply Depot goes to 8 feet.');else toast('8 feet. Your shovel won\'t go any deeper.')}
    sfx.thud();return;
  }
  const step=(!S.up.shovel?SIM.HANDS.scoop:S.up.spade?0.15:0.088)*tune('dig.depth')*(S.zeroT>0?2:1)*(myLevel()>=2?1.1:1);addXP(0.3);
  const d0=h.d;h.d=Math.min(maxD,h.d+step);fillBucket(h.d-d0);if(inVein(h.x,h.z))veinPay((h.d-d0)/FIVE_FT);   /* a rich vein (88-vein.js) */
  if(Math.random()<(S.up.shovel?SIM.SHOVEL_FLECK:SIM.HANDS.fleck)){S.seeds+=1;foundGold(1);sfx.coin();const n=performance.now();if(n-(scoop.fleckT||0)>4000){scoop.fleckT=n;toast('A fleck of gold! (+1)','gold',1800)}logEv('fleck',{})}   // the odd fleck you spot as you dig
  touchHole(h);h.mine=true;wsSend({t:'dig',x:h.x,z:h.z,d:+h.d.toFixed(2)});townCheckBreach(h);   // 5 ft at the old town's spot: the floor gives way (89-town.js)
  const y=groundAt(h.x,h.z)+0.4;puff(h.x+(Math.random()-0.5)*0.6,y,h.z+(Math.random()-0.5)*0.6,h.mx,h.mz,FP?2:6);sfx.scoop();throwClods(h,2);   // clods arc onto the spoil pile (46-holes.js)
  if(h.own&&!h.paid&&h.d>=FIVE_FT){h.paid=true;S.holesDone++;addXP(10);countUp('holes',25,'caveman');toast(`Hole #${S.holesDone} finished. Bucket: ${Math.floor(S.bucket*10)/10} of ${bucketMax()} holes of sand.`,'good');sfx.thud()}
  for(const it of items){
    if(it.found)continue;const dx=it.x-h.x,dz=it.z-h.z;
    if(dx*dx+dz*dz<(h.r*0.9)**2&&it.depth>h.d&&it.depth-h.d<HINT_AHEAD)hintFind(it,h);   // the shovel clinks on it a scoop or two early
    if(dx*dx+dz*dz<(h.r*0.9)**2&&it.depth<=h.d){
      if(!LOOT[it.type].key&&!LOOT[it.type].heavy&&S.sack.length>=sackMax()){if(now-lastWarn>2500){lastWarn=now;toast(`Your sack is full (${sackMax()} items). Sell to Mr. Pendanski at the Supply Depot, then come back for it.`,'bad')}continue}
      foundItem(it,h);
    }
  }
}
/* carried finds: about 1 in 3 ordinary finds is too big for the sack (more from deeper down), and comes up as a crate,
   a tool bundle or a jug that has to be carried to the Supply Depot window, worth more than the sack version. Sliders: F2 > Finds. */
function carryFind(it){
  const L=LOOT[it.type];if(L.key||L.heavy||S.inTown)return null;
  const p=tune('loot.carryOdds')+tune('loot.carryDeep')*clamp((it.depth-0.3)/1.15,0,1);if(Math.random()>=p)return null;
  const type=L.val<=12?'tools':L.val<=30?'crate':'jug';
  return{type,val:clamp(Math.round(L.val*tune('loot.carryValue')+10),5,SIM.HEAVY[type])};
}
function foundItem(it,h){
  const cv=carryFind(it);
  it.found=true;wsSend({t:'got',item:it.id,kb:it.type==='kb'});popItem(cv?{...it,type:cv.type}:it,h.x,h.z);
  const L=LOOT[it.type];
  if(cv){const C=LOOT[cv.type];sfx.clank();sfx.find();addXP(8);logEv('found',{item:it.id,type:it.type,carry:cv.type,value:cv.val,x:+h.x.toFixed(1),z:+h.z.toFixed(1)});
    toast(`You dug up a ${C.name.toLowerCase()} (${cv.val} gold). Too big for your sack: grab it (hold R) and carry it to Mr. Pendanski's window at the Supply Depot. ${C.note}`,'gold',6500);
    if(online())wsSend({t:'prop',item:it.id,type:cv.type,x:h.mx,z:h.mz,val:cv.val});else addProp(it.id,cv.type,h.mx,h.mz,cv.val);return}
  logEv('found',{item:it.id,type:it.type,value:L.val,x:+h.x.toFixed(1),z:+h.z.toFixed(1),heavy:!!L.heavy,kb:it.type==='kb'});
  if(it.type==='suitcase'){badge('stanley');sfx.gold();triggerWin(S.name,true);return}
  if(it.type==='kb'){S.hasKB=true;sfx.gold();toast('A gold tube marked "KB"! The Warden will want this. Take it to her cabin.','gold',6000);shout(2);return}
  if(L.heavy){sfx.clank();sfx.gold();addXP(20);toast(`You hit something big: ${L.name} (${L.val} gold). It won't fit in your sack. Grab it with F and haul it to Mr. Pendanski's window at the Supply Depot. Two campers carry it much faster.`,'gold',7000);
    if(online())wsSend({t:'prop',item:it.id,type:it.type,x:h.mx,z:h.mz});else addProp(it.id,it.type,h.mx,h.mz);return}
  S.sack.push(it.type);sfx.find();sfx.clank();addXP(4+L.val/4);toast(`Found: ${L.name} (worth ${L.val} gold). Sell it to Mr. Pendanski at the Supply Depot.`+(L.val>=40?' A rare one!':''),L.val>=40?'gold':'',3200);
}

/* ---------- the gold rush (sim.js GOLD): free water at the drums, and the sifter ---------- */
let panBusy=false;
function washPan(){   // the gold pan (no bucket yet): wash your sand at the drums
  if(panBusy||gfxBusy())return;const holes=S.bucket;panBusy=true;
  const r=SIM.siftGold(holes,Math.random,tune('gold.perHole')*goldScale(),RUN.mood==='digday'?2:1);   // what's in it is decided now; the pan shows it (89-goldfx.js)
  const pay=()=>{panBusy=false;S.bucket=0;S.seeds+=r.gold;foundGold(r.gold);addXP(4+r.gold/2);
    if(r.nugget||r.luck>1.4)sfx.gold();else sfx.coin();toast(`${r.nugget?'A NUGGET in the pan! ':''}You wash ${r.gold} gold out of your pan.`,r.nugget?'gold':'good',3800);logEv('pan',{holes:+holes.toFixed(2),gold:r.gold})};
  if(!gfxStart('pan',{gold:r.gold},pay))pay();
}
function fillCanteen(){
  if(carrier()==='pan'&&S.bucket>0.05){washPan();if(S.water<waterMax()-1)S.water=waterMax();return}
  if(S.water>=waterMax()-1){toast('Your canteen\'s already full.','',1800);return}
  S.water=waterMax();sfx.splash();toast('You fill your canteen at the drums.','good',2000);logEv('water',{});
}
let siftBusy=false;
function siftBucket(){
  if(siftBusy)return;
  if(hopperTier()&&carrier()==='bucket'){dumpHopper();return}   /* a hopper: dump and go (86-hopper.js) */
  if(carrier()!=='bucket'){toast(carrier()==='pan'?'The sifter takes a bucket of sand. Wash your pan at the water drums instead.':'You need a bucket to bring sand to the sifter. Start with a gold pan from the Supply Depot.','',4000);return}
  if(S.bucket<0.05){toast('Your bucket\'s empty. Go dig: every scoop of a hole fills it with sand.','',3200);return}
  if(gfxBusy())return;const holes=S.bucket;siftBusy=true;sfx.scoop();
  const r=SIM.siftGold(holes,Math.random,tune('gold.perHole')*goldScale(),RUN.mood==='digday'?2:1);
  const go=()=>{   // after the bucket's gone through (89-goldfx.js)
    siftBusy=false;S.bucket=0;
    S.seeds+=r.gold;foundGold(r.gold);addXP(5+r.gold/2);
    const how=r.nugget?'A NUGGET! ':r.luck>1.4?'A rich batch! ':r.luck<0.7?'Thin sand. ':'';
    if(r.nugget||r.luck>1.4){sfx.gold()}else sfx.coin();
    toast(`${how}The sifter shakes ${r.gold} gold out of ${Math.round(holes*10)/10} holes of sand.`,r.nugget||r.luck>1.4?'gold':'good',4200);
    logEv('sift',{holes:+holes.toFixed(2),gold:r.gold,luck:+r.luck.toFixed(2),nugget:r.nugget});
  };
  if(!gfxStart('sift',{holes,gold:r.gold},go))go();
}

/* ---------- interactions ---------- */
function nearSpot(){
  if(S.sit!=null)return seatedSpot();   // sitting down (86-sit.js)
  {const t=truckSpot();if(t&&S.inTruck)return t}   // in Mr. Sir's pickup: F only gets you out (87-truck.js)
  const dn=remoteNear(R=>R.f&2,2.4);if(dn)return{id:'revive',...dn};
  {const t=truckSpot();if(t)return t}
  if(S.inTown)return townSpot();   // the buried town's own spots (89-town.js)
  const tr=remoteNear(R=>R.f&16,3);if(tr)return{id:'pull',...tr};
  const sk=remoteNear(R=>R.f&32,SINK_RESCUE_R);if(sk)return{id:'sinkRescue',...sk};   // link hands with a sinkhole-trapped friend (hold F: see 87-sinkhole.js)
  {const br=breachNear(2.6);if(br)return{id:'townDown',k:br.k}}   // next to (or in) a hole that broke through: F to climb down (89-town.js)
  if(GRAB_ST.id!=null){const c=cartNear();if(c&&c.id!==GRAB_ST.id)return{id:'cartLoad',cart:c}}   // F: into the wheelbarrow (84-grab.js)
  if(S.carry!=null&&PROPS.has(S.carry))return{id:'drop',pr:PROPS.get(S.carry)};
  if(!inTent()){
    const pr=propNear(2.4);if(pr)return{id:'prop',pr};
    const b=bagNear(2);if(b)return{id:'bag',b};
  }
  {const g=grappleSpot();if(g)return g}   /* stuck, with a grapple hook (88-gear.js) */
  {const d=disarmSpot();if(d)return d}   /* beside a landmine with the kit (88-disarm.js) */
  {const so=sodaSpot();if(so)return so}   /* stock the soda machine (84-camp.js) */
  {const p=pipeSpot();if(p)return p}   /* the sand pipeline: lay it, dump into it, fix it (88-pipeline.js) */
  for(const s of SPOTS){
    const roomSpot=s.id==='exit'||s.id==='bunk'||s.id==='cards'||s.id==='office';
    if(roomSpot?S.tent==null||(s.ti!=null&&s.ti!==S.tent)||(s.id==='bunk'&&BUNKS[s.bi].tent!==S.tent)||(s.id==='cards'&&S.tent!==TENTS.indexOf(D_TENT)):S.tent!=null)continue;
    if((P.x-s.x)**2+(P.z-s.z)**2<s.r*s.r)return s;
  }
  {const t=sitSpot();if(t)return t}   // a free bench or stool (86-sit.js)
  let best=null,bd=2.8*2.8;
  for(const b of bots){if(!b.p.g.visible)continue;const dx=b.p.g.position.x-P.x,dz=b.p.g.position.z-P.z,d2=dx*dx+dz*dz;if(d2<bd){bd=d2;best=b}}
  return best?{id:'bot',bot:best}:null;
}
function use(){
  const s=nearSpot();if(!s||S.ko||uiOpen())return;
  if(s.id==='revive')return; // hold F: handled in updateCoop
  if(s.id==='pull'){wsSend({t:'pull',id:s.rid});addXP(15);countUp('helps',10,'ladder');toast(`You pulled ${s.R.name} out of the hole.`,'good',2000);sfx.thud();return}
  if(s.id==='sinkRescue')return; // hold F to link hands: handled every frame in updateSinkholes (87-sinkhole.js)
  if(s.id==='drop'){S.carry=null;toast('You let go.','',1200);return}
  if(s.id.startsWith('town')&&townUse(s))return;
  if(s.id==='cartLoad'){loadIntoCart();return}
  if(s.id==='prop'){useProp(s.pr);return}   // grab it / let go (84-grab.js)
  if(s.id==='bag'){if(online())wsSend({t:'grab',id:s.b.id});else{takeBag(s.b.items,s.b.n);removeBag(s.b.id)}return}
  if(s.use){s.use();return}   // a spot that brings its own action (another map's rope anchor: 88-zones.js)
  if(s.id==='water'){fillCanteen();return}
  if(s.id==='sift'){siftBucket();return}
  if(s.id==='disarm'||s.id==='grapple')return;   // hold F: 88-disarm.js
  else if(s.id==='warden')openDialog('warden');
  else if(s.id==='store')openShop();
  else if(s.id==='cards')openCards();
  else if(s.id==='office')readWardenNote();   // her ledgers, and a note on the old town (89-town.js)
  else if(s.id==='bot')openDialog('bot',s.bot);
  else if(s.id==='tentdoor')enterTent(s.ti);
  else if(s.id==='exit')exitTent();
  else if(s.id==='bunk')toggleBunk(s.bi);
}
